import json
from pathlib import Path
for page in sorted(Path('world/pages').glob('missions-*.json')):
    for item in json.loads(page.read_text())['items']:
        mission = item['mission_id']
        goal = item.get('goal', '').lower()
        if 'SQLITE' in mission and ('VERDICT' in mission or 'OUTCOME' in mission or ('checkpoint' in goal and '2026-11-22' in goal)):
            print(json.dumps({k: item.get(k) for k in ('mission_id','status','agent_id','lease_expires_at','evidence')}))
